check('neutral representation owns layers and filters','List<RepresentationLayerDefinition> layers' in rep and 'List<RepresentationFilterDefinition> filters' in rep)
check('inactive layers excluded from default mappings','defaultActiveMappingIds' in rep and 'layer.activeByDefault()' in rep)
check('layer contract preserves activation and membership',all(x in layer for x in ['defaultLayer','activeByDefault','userToggleable','nodeMappingIds','edgeMappingIds','toolIds']))
check('external filters are non executable without canonical expression','boolean executable()' in flt and 'conditionExpressionId' in flt and 'externalCondition' in flt)
