check('runtime compiler preserves external filter review metadata','externalFilterCount' in compiler and 'representation.filters()' in compiler)
check('schema exposes neutral layers','$defs' in schema and 'representationLayer' in schema['$defs'] and 'representationFilter' in schema['$defs'])
check('schema representation exposes layers and filters','layers' in schema['$defs']['representation']['properties'] and 'filters' in schema['$defs']['representation']['properties'])
check('project images remain schema-valid','PROJECT_IMAGE' in schema['$defs']['nodeMapping']['properties']['shape']['enum'])
check('Sirius importer recognizes default/additional layers','isLayer(' in visual and 'additionallayers' in visual)
check('Sirius importer associates mappings and tools with layers','nearestLayer' in visual and 'layer.nodeMappingIds.add' in visual and 'layer.edgeMappingIds.add' in visual and 'layer.toolIds.add' in visual)
check('Sirius importer preserves composite filters','isCompositeFilter' in visual and 'RepresentationFilterDefinition' in visual and 'hydra.import.reviewRequired' in visual)
check('Sirius external AQL filters are never promoted to canonical expressions','new RepresentationFilterDefinition(raw.id, raw.name, raw.activeByDefault, mappingIds, "", raw.externalCondition' in visual)
check('semantic edge descriptor contains real edge object semantics',all(x in semantic for x in ['edgeClassId','sourceRelationId','targetRelationId','containmentRelationId','defaultValues']))
check('Sirius semantic edge tool recovers containment and defaults','enrichSemanticEdgeFromTool' in visual and 'recoverToolDefaultAttributes' in visual)
check('Sirius exporter has no recursive edge tool call',sirius.count('appendEdgeCreationTool(xml, metamodel, editor, representation, edge, indent + "  ")')==1 and 'appendEdgeCreationTool(xml, metamodel, editor, representation, edge);' not in sirius)
check('Sirius exporter emits additional layers','<additionalLayers name=' in sirius and 'layer.activeByDefault()' in sirius)
check('Sirius exporter emits safe preserved AQL filters','CompositeFilterDescription' in sirius and 'MappingFilter' in sirius and 'condition.startsWith("aql:")' in sirius)
check('Sirius exporter resolves mapping paths by owning layer','mappingPath(' in sirius and '@additionalLayers[name=' in sirius)
check('Sirius exporter creates semantic edge objects','CreateInstance' in sirius and 'var:source' in sirius and 'var:target' in sirius)
check('external project pipeline invokes semantic visual adapters','materializeVisuals' in external and 'importSirius' in external and 'importGmf' in external and 'importSiriusWeb' in external)
check('external project pipeline recovers code-driven editors','codeVisualRecovery.recover' in external and 'persistRecoveredEditor' in external)
check('code-driven recovery prioritizes canonical snapshots','recoverCanonical' in codevisual and 'editor_definition.json' in codevisual and 'canonicalRoundTrip' in codevisual)
