check('GLSP recovery does not execute imported code',all(x not in codevisual for x in ['ProcessBuilder','Runtime.getRuntime','ScriptEngine','Class.forName','exec(']))
check('Langium validators recovered statically','LANGIUM_CHECK' in validation and 'parseLangiumChecks' in validation and 'ValidationAcceptor' in validation)
check('Langium code actions are review-only','parseLangiumCodeActions' in validation and 'LANGIUM_TYPESCRIPT' in validation and 'hydra.import.reviewOnly' in validation)
check('BESSER Python validators recovered statically','PY_CHECK' in validation and 'parseBesserChecks' in validation and 'BESSER_PYTHON' in validation)
check('BESSER Python quick fixes never execute imported Python','parseBesserFixes' in validation and all(x not in validation for x in ['ProcessBuilder','Runtime.getRuntime','PythonInterpreter','exec(']))
check('external validation pipeline links fixes by rule name or issue code','linkedFixes(fixesByRule, recovered.name(), recovered.code())' in validation)
check('complete Sirius fixture is embedded',(ROOT/'src/test/resources/fixtures/sirius-complete/com.hydra.sirius.fixture.design/description/hydratest.odesign').is_file())
check('fixture regression requires diagram table and tree',all(x in fixturetest for x in ['Hydra Workflow Diagram','Workflow Elements Table','Workflow Tree']))
check('fixture regression requires layers and filters',all(x in fixturetest for x in ['Diagnostics','Hide completed tasks','defaultActiveMappingIds','externalCondition']))
check('fixture regression requires semantic Connection object',all(x in fixturetest for x in ['semanticObjectBacked','Connection','sourceRelationId','targetRelationId','containmentRelationId']))
check('fixture regression requires Sirius validations',all(x in fixturetest for x in ['NonEmptyName','ProgressRange','NoSelfLoop']))
check('fixture runtime switches diagram table and tree projections',all(x in runtimefixture for x in ['RepresentationKind.DIAGRAM','RepresentationKind.TABLE','RepresentationKind.TREE','TaskSquare','NodeLine','Nodes']))
check('fixture runtime renders semantic edge endpoints',all(x in runtimefixture for x in ['relationInstanceId()).isEqualTo("element:connection")','sourceElementId()).isEqualTo("element:start")','targetElementId()).isEqualTo("element:task")']))
check('recovered editor enables live validation and quick-fix runtime',all(x in materialization for x in ['EditorCapability.VALIDATION_RUNTIME','EditorCapability.QUICK_FIX_RUNTIME','EditorValidationTrigger.ON_CHANGE','EditorValidationTrigger.ON_REPRESENTATION_CHANGE']))
check('editor session validates automatically after semantic changes','automaticValidation(next, plan, EditorValidationTrigger.ON_CHANGE' in sessionservice and 'validationRuntime.validate' in sessionservice)
check('editor session exposes quick-fix resolve preview apply cycle',all(x in sessionservice for x in ['List<QuickFixDescriptor> quickFixes','QuickFixPreviewResult previewQuickFix','EditorSessionQuickFixResult applyQuickFix','quickFixRuntime.execute']))
check('safe imported rules and fixes are regression tested',all(x in validationfixture for x in ['ProgressRange','PositiveDuration','Clamp progress to 100','Set duration to 1 minute','reviewOnly']))
check('model editor renders diagnostics and quick-fix controls',all(x in sessionui for x in ['view.validationReport?.diagnostics','listEditorSessionQuickFixes','previewEditorSessionQuickFix','applyEditorSessionQuickFix','Available quick fixes']))
check('frontend regression switches imported representations','switches to the selected imported representation' in sessionuitest and 'switchEditorSessionRepresentation' in sessionuitest)
check('frontend regression offers and applies quick fixes','shows validation diagnostics and offers safe quick fixes inside the model editor' in sessionuitest and 'Clamp progress to 100' in sessionuitest)
check('modal close callback is held by stable ref','onCloseRef' in modal and '[open]' in modal)
check('modal select focus regression exists','keeps focus inside an active control' in modaltest and 'select.focus()' in modaltest)

failed=[n for n,o in checks if not o]
print(f'EXTERNAL_MULTILAYER_IMPORT={len(checks)-len(failed)}/{len(checks)}')
if failed:
    for n in failed: print('FAIL :: '+n)
sys.exit(1 if failed else 0)
